{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Ipratropium bromide, a quaternary ammonium tropane ester with the same tropic acid ester and permanent cationic head as the query, has an absolute oral bioavailability of 2.0% in healthy volunteers, directly supporting a low F (<20%) prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tiotropium bromide, which shares the epoxide-fused quaternary tropane scaffold of the query, has an absolute oral bioavailability of only 2–3% after oral solution in healthy volunteers, supporting low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Ipratropium's low oral bioavailability is partly attributed to active intestinal secretion of the quaternary ammonium cation, a mechanism that is also expected to limit the query's oral absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester (N-butylscopolamine-like). Close analogues ipratropium and tiotropium have absolute oral bioavailability of 2–3% in humans, far below the 20% threshold, due to permanent charge and active intestinal secretion. Therefore predict low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the exact query molecule was provided; prediction relies on close structural analogues.",
    "One ipratropium record (C42) reports ~32% absorption, conflicting with multiple absolute bioavailability studies; this outlier was not used as primary evidence.",
    "Tropisetron, a non-quaternary tropane, shows higher oral bioavailability, but its lack of a permanent positive charge limits transferability to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

